set -euo pipefail; python3 - <<'PY'
from pathlib import Path
needles=('runClimateV6RealInputRuntime','Stage28ServiceConsole')
for p in Path('.').rglob('*'):
    if not p.is_file() or '.git' in p.parts or 'build' in p.parts:
        continue
    try: s=p.read_text(errors='ignore')
    except Exception: continue
    if any(n in s for n in needles):
        lines=s.splitlines()
        print(f'AUDIT_FILE {p} lines={len(lines)} bytes={len(s.encode())}')
        for n in needles:
            for i,line in enumerate(lines,1):
                if n in line:
                    lo=max(1,i-4); hi=min(len(lines),i+12)
                    print(f'AUDIT_SYMBOL {n} {p}:{i}')
                    for j in range(lo,hi+1): print(f'{j:5d}: {lines[j-1]}')
PY
